const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app is loaded with no existing todos', function () {
  this.localStorage.clear();
  // App is already loaded via Before hook in world.js
});

Given('the user has added a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user types {string} in the new-todo input and presses Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user presses Enter without typing', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = '';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user toggles the first todo', function () {
  const toggle = this.document.querySelector('.todo-list li .toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user deletes the first todo', function () {
  const destroy = this.document.querySelector('.todo-list li .destroy');
  destroy.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When('the user double-clicks the first todo label', function () {
  const label = this.document.querySelector('.todo-list li label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user changes the edit input to {string} and presses Enter', function (value) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When('the user changes the edit input to {string} and presses Escape', function (value) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

When('the user clicks {string}', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
      break;
    }
  }
});

When('the user clicks the toggle-all checkbox', function () {
  const checkbox = this.document.getElementById('toggle-all');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  this.loadApp();
});

Then('a todo {string} appears in the list', function (title) {
  const labels = this.document.querySelectorAll('.todo-list li label');
  const texts = Array.from(labels).map(l => l.textContent);
  expect(texts).to.include(title);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

Then('the todo count shows {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  expect(count.textContent.trim()).to.equal(text);
});

Then('no todos exist', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(0);
});

Then('the todo list shows {int} todos', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the first todo is marked completed', function () {
  const first = this.document.querySelector('.todo-list li');
  expect(first.classList.contains('completed')).to.be.true;
});

Then('the first todo is not marked completed', function () {
  const first = this.document.querySelector('.todo-list li');
  expect(first.classList.contains('completed')).to.be.false;
});

Then('the todo list shows {int} todo', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the remaining todo is {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list li label');
  const texts = Array.from(labels).map(l => l.textContent);
  expect(texts).to.include(title);
});

Then('the {string} button is hidden', function (buttonText) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === buttonText) {
      expect(btn.style.display).to.equal('none');
      break;
    }
  }
});

Then('all todos are marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    expect(item.classList.contains('completed')).to.be.true;
  }
});

Then('no todos are marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    expect(item.classList.contains('completed')).to.be.false;
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  expect(checkbox.checked).to.be.false;
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.equal('none');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.equal('none');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.not.equal('none');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.not.equal('none');
});

Then('the {string} filter is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters li a');
  for (const link of links) {
    if (link.textContent.trim() === filterName) {
      expect(link.classList.contains('selected')).to.be.true;
    }
  }
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  expect(this.document.activeElement).to.equal(input);
});

(function () {
	'use strict';

	var STORAGE_KEY = 'todos-shakedown';
	var newTodoInput = document.querySelector('.new-todo');
	var todoList = document.querySelector('.todo-list');
	var toggleAllCheckbox = document.getElementById('toggle-all');
	var todoCount = document.querySelector('.todo-count');
	var mainSection = document.querySelector('.main');
	var footer = document.querySelector('.footer');
	var clearCompletedBtn = document.querySelector('.clear-completed');
	var filters = document.querySelectorAll('.filters li a');

	function loadTodos() {
		try {
			return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
		} catch (e) {
			return [];
		}
	}

	function saveTodos(todos) {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function generateId() {
		return Date.now().toString(36) + Math.random().toString(36).slice(2);
	}

	function getActiveFilter() {
		var hash = window.location.hash || '#/';
		if (hash === '#/active') return 'active';
		if (hash === '#/completed') return 'completed';
		return 'all';
	}

	function getFilteredTodos(todos) {
		var filter = getActiveFilter();
		if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
		if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
		return todos;
	}

	function render() {
		var todos = loadTodos();
		var filtered = getFilteredTodos(todos);
		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = todos.filter(function (t) { return t.completed; }).length;

		// Clear list
		todoList.innerHTML = '';

		// Render todos
		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.dataset.id = todo.id;
			if (todo.completed) li.classList.add('completed');

			var viewDiv = document.createElement('div');
			viewDiv.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			checkbox.checked = todo.completed;

			var label = document.createElement('label');
			label.textContent = todo.title;

			var destroyBtn = document.createElement('button');
			destroyBtn.className = 'destroy';

			viewDiv.appendChild(checkbox);
			viewDiv.appendChild(label);
			viewDiv.appendChild(destroyBtn);

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;

			li.appendChild(viewDiv);
			li.appendChild(editInput);
			todoList.appendChild(li);
		});

		// Update counter
		var itemText = activeCount === 1 ? 'item' : 'items';
		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';

		// Show/hide main and footer
		if (todos.length === 0) {
			mainSection.style.display = 'none';
			footer.style.display = 'none';
		} else {
			mainSection.style.display = '';
			footer.style.display = '';
		}

		// Update toggle-all
		toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

		// Update clear completed visibility
		clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

		// Update filter links
		filters.forEach(function (link) {
			link.classList.remove('selected');
		});
		var activeFilter = getActiveFilter();
		filters.forEach(function (link) {
			if ((activeFilter === 'all' && link.getAttribute('href') === '#/') ||
				(activeFilter === 'active' && link.getAttribute('href') === '#/active') ||
				(activeFilter === 'completed' && link.getAttribute('href') === '#/completed')) {
				link.classList.add('selected');
			}
		});
	}

	function addTodo(title) {
		var trimmed = title.trim();
		if (trimmed === '') return;
		var todos = loadTodos();
		todos.push({ id: generateId(), title: trimmed, completed: false });
		saveTodos(todos);
		render();
	}

	function toggleTodo(id) {
		var todos = loadTodos();
		todos = todos.map(function (t) {
			if (t.id === id) {
				return { id: t.id, title: t.title, completed: !t.completed };
			}
			return t;
		});
		saveTodos(todos);
		render();
	}

	function deleteTodo(id) {
		var todos = loadTodos();
		todos = todos.filter(function (t) { return t.id !== id; });
		saveTodos(todos);
		render();
	}

	function editTodo(id, newTitle) {
		var trimmed = newTitle.trim();
		var todos = loadTodos();
		if (trimmed === '') {
			todos = todos.filter(function (t) { return t.id !== id; });
		} else {
			todos = todos.map(function (t) {
				if (t.id === id) {
					return { id: t.id, title: trimmed, completed: t.completed };
				}
				return t;
			});
		}
		saveTodos(todos);
		render();
	}

	function toggleAll() {
		var todos = loadTodos();
		var allCompleted = todos.every(function (t) { return t.completed; });
		todos = todos.map(function (t) {
			return { id: t.id, title: t.title, completed: !allCompleted };
		});
		saveTodos(todos);
		render();
	}

	function clearCompleted() {
		var todos = loadTodos();
		todos = todos.filter(function (t) { return !t.completed; });
		saveTodos(todos);
		render();
	}

	// Event: new todo input
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.key === 'Enter') {
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	});

	// Event delegation for todo list
	todoList.addEventListener('click', function (e) {
		var li = e.target.closest('li');
		if (!li) return;
		var id = li.dataset.id;

		if (e.target.classList.contains('toggle')) {
			// Use checked state from DOM to match the click
			var todo = loadTodos().find(function (t) { return t.id === id; });
			if (todo) {
				var todos = loadTodos().map(function (t) {
					if (t.id === id) return { id: t.id, title: t.title, completed: e.target.checked };
					return t;
				});
				saveTodos(todos);
				render();
			}
		} else if (e.target.classList.contains('destroy')) {
			deleteTodo(id);
		}
	});

	// Also handle toggle via change event (for programmatic changes)
	todoList.addEventListener('change', function (e) {
		if (!e.target.classList.contains('toggle')) return;
		var li = e.target.closest('li');
		if (!li) return;
		var id = li.dataset.id;
		var todos = loadTodos().map(function (t) {
			if (t.id === id) return { id: t.id, title: t.title, completed: e.target.checked };
			return t;
		});
		saveTodos(todos);
		render();
	});

	// Double-click to edit
	todoList.addEventListener('dblclick', function (e) {
		if (e.target.tagName !== 'LABEL') return;
		var li = e.target.closest('li');
		if (!li) return;
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.focus();
	});

	// Edit input events
	todoList.addEventListener('keydown', function (e) {
		if (e.target.classList.contains('edit')) {
			var li = e.target.closest('li');
			var id = li.dataset.id;
			if (e.key === 'Enter') {
				li.classList.remove('editing');
				editTodo(id, e.target.value);
			} else if (e.key === 'Escape') {
				li.classList.remove('editing');
				render();
			}
		}
	});

	todoList.addEventListener('blur', function (e) {
		if (e.target.classList.contains('edit')) {
			var li = e.target.closest('li');
			if (!li) return;
			var id = li.dataset.id;
			li.classList.remove('editing');
			editTodo(id, e.target.value);
		}
	}, true);

	// Toggle all
	toggleAllCheckbox.addEventListener('change', function () {
		toggleAll();
	});

	// Clear completed
	clearCompletedBtn.addEventListener('click', function () {
		clearCompleted();
	});

	// Filter links
	filters.forEach(function (link) {
		link.addEventListener('click', function (e) {
			e.preventDefault();
			var href = link.getAttribute('href');
			if (window.location.hash !== href) {
				window.location.hash = href;
			}
		});
	});

	// Hash change
	window.addEventListener('hashchange', function () {
		render();
	});

	// Initial render
	render();

	// Ensure focus on new-todo input (autofocus may not work in all environments)
	if (newTodoInput) newTodoInput.focus();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Persistent localStorage across Window instances (happy-dom scopes per-Window).
  static _persistedStorage = {};

  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // Save current localStorage before destroying the old Window.
    if (this.window && this.window.localStorage) {
      this._saveStorage();
    }

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore persisted localStorage into the new Window (happy-dom scopes per-Window).
    for (const [key, value] of Object.entries(AppWorld._persistedStorage)) {
      this.window.localStorage.setItem(key, value);
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Persist localStorage snapshot for the next Window instance.
  _saveStorage() {
    if (!this.window || !this.window.localStorage) return;
    AppWorld._persistedStorage = {};
    for (let i = 0; i < this.window.localStorage.length; i++) {
      const key = this.window.localStorage.key(i);
      AppWorld._persistedStorage[key] = this.window.localStorage.getItem(key);
    }
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    // Save localStorage before disposing so it persists to the next Window.
    this._saveStorage();
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () {
  // Clear persisted storage so each scenario starts fresh.
  AppWorld._persistedStorage = {};
  this.loadApp();
});
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

